}

function TaglineJustifyBase({
  words: wordsProp,
  text = "Your launch deserves a film as good as the product.",
  highlight = "film",
  stagger = STAGGER,
  logo,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  grain = true,
  scale = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: TaglineJustifyProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps } = useSceneConfig();
  const u = H / 720;
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const words = useMemo(
    () => wordsProp ?? text.trim().split(/\s+/),
    [wordsProp, text],
  );
  const target = clean(highlight);
  const widths = useMemo(
    () =>
      words.map((w) =>
        target !== "" && clean(w) === target ? serifEm(w) : em(w),
      ),
    [words, target],
  );
  const layout = useMemo(
    () =>
      justifyLayout(
        widths,
        words.findIndex((w) => target !== "" && clean(w) === target),
      ),
    [widths, words, target],
  );
  const { lines } = layout;

  const unitH = stackHeight(layout.sizes);
  const B = Math.min(W * 0.6, (H * 0.62) / unitH);
  const sizes = layout.sizes.map((k) => k * B);
  const blockH = unitH * B;
  const footGap = 44 * u;
  const footH = 26 * u;
  const groupH = blockH + footGap + footH;
  const left = (W - B) / 2;
  const capTop = (H - groupH) / 2;
  const baselines: number[] = [];
  sizes.forEach((F, i) => {
    baselines.push(
      i === 0
        ? capTop + CAP * F
        : baselines[i - 1] + DESC * sizes[i - 1] + ASC * F,
    );
  });
  const arrive = (j: number) => FIRST + j * stagger;
  const settle = (j: number) =>
    spring({
      frame: t - arrive(j),
      fps,
      config: { damping: 17, stiffness: 170, mass: 0.8 },
    });
  const push = interpolate(t, [0, 160], [0, 1], CLAMP);

  const nodes: React.ReactNode[] = [];
  const key: { box: { x: number; y: number; w: number; h: number } | null } = {
    box: null,
  };
  const sweep = interpolate(t, [0, 160], [0, 1], CLAMP);
  const swirlFill = `linear-gradient(${100 + sweep * 14}deg, ${c.swirl[0]} 0%, ${c.swirl[1]} ${42 + sweep * 6}%, ${c.swirl[2]} 100%)`;
  lines.forEach((line, li) => {
    const F = sizes[li];
    const width = B / F;
    const n = line.length;
    const levels: number[] = [];
    for (let m = 2; m <= n; m++) {
      const sum = line.slice(0, m).reduce((a, j) => a + widths[j], 0);
      levels[m] = (width - sum) / (m - 1);
    }
    levels[1] = (levels[2] ?? SPACE) + 1.1;
    const gapAt = (settled: (j: number) => number) => {
      let g = levels[1];
      for (let m = 2; m <= n; m++) {
        g += (levels[m] - levels[m - 1]) * settled(line[m - 1]);
      }
      return g;
    };
    const gap = gapAt(settle);
    const gapRest = gapAt(() => 1);
    let x = 0;
    let xRest = 0;
    line.forEach((j, k) => {
      const s = settle(j);
      const firstIn = k === 0 ? (1 - s) * 0.5 : 0;
      const o = interpolate(t, [arrive(j), arrive(j) + 6], [0, 1], CLAMP);
      const isKey = target !== "" && clean(words[j]) === target;
      const fill = isKey
        ? interpolate(t, [80, 98], [0, 1], { ...CLAMP, easing: EASE_IO })
        : 0;
      const anchor = k === 0 ? x : x + widths[j];
      const size = isKey ? F * SERIF_SCALE : F;
      // The highlight paints a clipped box, and layout rounds a box edge to
      // whole pixels: it is laid out where it settles and slides there by
      // transform. Plain words keep their `left`; their glyphs place
      // sub-pixel on x.
      const restAnchor = k === 0 ? xRest : xRest + widths[j];
      const dx = isKey ? (anchor + firstIn - restAnchor) * F : 0;
      const slide = Math.abs(dx) > 1e-3 ? `translateX(${dx}px)` : "";
      const lean = k === 0 ? "" : "translateX(-100%)";
      if (isKey) {
        key.box = {
          x: left + (anchor + firstIn - (k === 0 ? 0 : widths[j])) * F,
          y: baselines[li],
          w: widths[j] * F,
          h: CAP * F,
        };
      }
      nodes.push(
        <div
          key={j}
          style={{
            position: "absolute",
            top: baselines[li] - (isKey ? SERIF_BASELINE : BASELINE) * size,
            left: left + (isKey ? restAnchor : anchor + firstIn) * F,
            transform: [slide, lean].filter(Boolean).join(" ") || undefined,
            fontFamily: isKey ? serif : fontFamily,
            fontStyle: isKey ? "italic" : "normal",
            fontWeight: isKey ? 400 : 500,
            fontSize: size,
            lineHeight: 1,
            letterSpacing: `${isKey ? SERIF_TRACK : TRACK}em`,
            whiteSpace: "pre",
            color: fg,
            opacity: o,
          }}
        >
          {words[j]}
          {isKey ? (
            <span
              style={{
                position: "absolute",
                inset: "-0.1em -0.12em",
                padding: "0.1em 0.12em",
                color: "transparent",
                backgroundImage: swirlFill,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                clipPath: `inset(-10% ${(1 - fill) * 100}% -10% -2%)`,
              }}
            >
              {words[j]}
            </span>
          ) : null}
        </div>,
      );
      x += widths[j] + gap;
      xRest += widths[j] + gapRest;
    });
  });

  const foot = (d: number) =>
    interpolate(t, [90 + d, 112 + d], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const ruleP = interpolate(t, [84, 108], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const footTop = capTop + blockH + footGap;
  const emberIn = interpolate(t, [78, 110], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {background === undefined ? (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse 60% 70% at 50% 40%, ${c.key}, transparent 72%)`,
          }}
        />
      ) : null}
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${1 + push * 0.025})${glide(midway(push))}`,
            transformOrigin: "50% 45%",
          }}
        >
          {key.box ? (
            <div
              style={{
                position: "absolute",
                left: key.box.x - key.box.w * 0.9,
                width: key.box.w * 2.8,
                top: key.box.y - key.box.h * 1.6,
                height: key.box.h * 2.6,
                background: `radial-gradient(50% 50% at 50% 50%, ${c.ember} 0%, transparent 70%)`,
                opacity: emberIn,
              }}
            />
          ) : null}
          {nodes}
          <div
            style={{
              position: "absolute",
              left,
              top: footTop - 18 * u,
              width: B,
              height: Math.max(1, u),
              background: `linear-gradient(90deg, ${accent} 0px, ${accent} ${36 * u}px, ${c.hair} ${36 * u}px)`,
              transform: `scaleX(${ruleP})`,
              transformOrigin: "0% 50%",
            }}
          />
          <div
            style={{
              position: "absolute",
              left,
              top: footTop,
              height: footH,
              display: "flex",
              alignItems: "center",
              gap: 9 * u,
              opacity: foot(0),
              transform: `translateY(${(1 - foot(0)) * 10 * u}px)`,
            }}
          >
            {logo ?? <RemocnLogo fontSize={24 * u} color={fg} />}
          </div>
        </AbsoluteFill>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

